(()=>{'use strict';const form=document.getElementById('technical-filter');if(!form)return;const query=document.getElementById('technical-query'),cat=document.getElementById('technical-category'),review=document.getElementById('technical-review'),result=document.getElementById('technical-results'),status=document.getElementById('technical-status'),more=document.getElementById('technical-more');let records=[],checked=new Set(),limit=18;const norm=s=>s.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');function render(){const tokens=norm(query.value).split(/\s+/).filter(Boolean);const found=records.filter(a=>(cat.value==='all'||a.category===cat.value)&&(review.value==='all'||checked.has(a.url.replace(/\.html$/,'')))&&tokens.every(t=>norm(a.title+' '+a.description).includes(t)));result.replaceChildren();found.slice(0,limit).forEach(a=>{const box=document.createElement('article');box.className='growth-card';const h=document.createElement('h2'),link=document.createElement('a'),p=document.createElement('p'),badge=document.createElement('p');link.href=a.url;link.textContent=a.title;h.append(link);p.textContent=a.description;badge.textContent=a.category+(checked.has(a.url.replace(/\.html$/,''))?' · Kaynaklı inceleme · tarih yazıda belirtilir':'');box.append(badge,h,p);result.append(box)});status.textContent=found.length+' sonuç · '+Math.min(found.length,limit)+' gösteriliyor';more.hidden=found.length<=limit}form.addEventListener('submit',e=>{e.preventDefault();limit=18;render()});[query,cat,review].forEach(el=>el.addEventListener(el===query?'input':'change',()=>{limit=18;render()}));more.addEventListener('click',()=>{limit+=18;render()});Promise.all([fetch('/assets/content-index.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('/assets/editorial-reviewed-20261015.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([data,done])=>{records=data.filter(a=>a.kind==='editorial');checked=new Set(done);render()}).catch(()=>{status.textContent='Arama dizini yüklenemedi. Blog koleksiyonu ve teknik kütüphane bağlantılarını kullanabilirsiniz.'})})();